import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';
import { createRequire } from 'node:module';

const root = new URL('../../', import.meta.url);
const upstream = new URL('./', pathToFileURL(createRequire(import.meta.url).resolve('3dmol/package.json')));
export const prepare3DMol = async () => {
  const lock = JSON.parse(await readFile(new URL('script/3dmol/runtime.lock.json', root), 'utf8'));
  const metadata = JSON.parse(await readFile(new URL('package.json', upstream), 'utf8'));
  assert.equal(metadata.version, lock.version, 'Review the 3Dmol compatibility patch before upgrading');
  const original = await readFile(new URL('build/3Dmol.js', upstream));
  assert.equal(createHash('sha256').update(original).digest('hex'), lock.sha256, '3Dmol input differs from the audited distribution');
  const source = original.toString('utf8');
  assert.equal(source.split(lock.methodStart).length - 1, 1, '3Dmol initGL must match exactly once');
  assert.equal(source.split(lock.nextMethod).length - 1, 1, '3Dmol next-method boundary must match exactly once');
  const start = source.indexOf(lock.methodStart);
  const end = source.indexOf(lock.nextMethod, start);
  assert.ok(end > start, '3Dmol initGL boundaries changed');
  const method = await readFile(new URL('script/3dmol/initGL.js.txt', root), 'utf8');
  const patched = source.slice(0, start) + method.replaceAll('\r\n', '\n') + source.slice(end);
  // Keep the UMD factory private inside an ES module: no window.$3Dmol or
  // synthetic OffscreenCanvas global. Its own HTML canvas fallback is retained.
  const runtime =
    '// Generated by script/3dmol/prepare.mjs; see the pinned compatibility recipe.\nconst module = { exports: {} };\nconst exports = module.exports;\n' +
    patched.replace(/^\/\/# sourceMappingURL=.*$/gm, '') +
    '\nexport default module.exports;\n';
  const license = await readFile(new URL('LICENSE', upstream));
  for (const directory of ['src/markdown/extensions/molecule-3d/vendor/', 'dist/source/markdown/extensions/molecule-3d/vendor/']) {
    const target = new URL(directory, root);
    await mkdir(target, { recursive: true });
    await writeFile(new URL('3dmol.js', target), runtime);
    await writeFile(new URL('LICENSE', target), license);
  }
  console.log(`Prepared private 3Dmol ${lock.version} runtime with safe OffscreenCanvas detection`);
};

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) await prepare3DMol();
